#include "arbitrage_checker.hpp"#include <algorithm>// =====================================================================// Example numbers//   spot ask = 100, future bid = 102, qty = 10//   spot fee = 0.10%, future fee = 0.04%//   slippage = 0.01% (har leg pe), buffer = 0.02%// Below code operates on 1e8 scale// =====================================================================// validating tick, whether its greater than 0 or not// Example: ask = 100, bid = 99, qty = 5 -> valid//          ask = 0 -> invalidbool arbitrage_checker::is_valid(const tick& t){    return t.ask > 0 && t.bid > 0 && t.ask_qty > 0 && t.bid_qty > 0;}// (a * b) / d , converting to __int128, to stop an overflow of int64.// Example: a = 1000, b = 11, d = 10000  ->  1000 * 11 / 10000 = 1.1// converting price and qty to 1e8 scale to overcome decimal points problem during entire calculationint64_t arbitrage_checker::mul_div(int64_t a, int64_t b, int64_t d){    return static_cast<int64_t>((static_cast<__int128>(a) * b) / d);}// Notional = price * qty (total amount of trade).// divided by QTY_SCALE to keep in same range// Example: price = 100, qty = 10  ->  notional = 100 * 10 = 1000int64_t arbitrage_checker::notional(int64_t price, int64_t qty){    return mul_div(price, qty, QTY_SCALE);}//order cost = notional * (fee + slippage).// Example: notional = 1000, spot fee = 0.10%, slippage = 0.01%//          rate = 0.10% + 0.01% = 0.11%//          cost = 1000 * 0.11% = 1.1int64_t arbitrage_checker::order_cost(int64_t notional_amount, int64_t fee_rate) const{    return mul_div(notional_amount, fee_rate + slippage_, RATE_SCALE);}// calculating spread + cost and then profitable or not// buy_price  = spot or future// sell_price = spot or futurearbitrage_result arbitrage_checker::build_result(arbitrage_direction dir,                                                 int64_t buy_price, int64_t sell_price, int64_t qty,                                                 int64_t buy_fee_rate, int64_t sell_fee_rate) const{    // Step 1: calculates notional of both sides    // Example: buy_price = 100, sell_price = 102, qty = 10    //          buy_notional  = 100 * 10 = 1000    //          sell_notional = 102 * 10 = 1020    const int64_t buy_notional  = notional(buy_price, qty);    const int64_t sell_notional = notional(sell_price, qty);    // Step 2: gross profit = profit before cost    // Example: 1020 - 1000 = 20    const int64_t gross_profit = sell_notional - buy_notional;    // Step 3: trade entry cost = both legs trade fees + slippage    // Example (buy leg = spot 0.10%, sell leg = future 0.04%, slippage 0.01% both side):    //          buy leg cost  = 1000 * (0.10% + 0.01%) = 1000 * 0.11% = 1.1    //          sell leg cost = 1020 * (0.04% + 0.01%) = 1020 * 0.05% = 0.51    //          trade_cost    = 1.1 + 0.51 = 1.61    const int64_t trade_cost = order_cost(buy_notional, buy_fee_rate)                             + order_cost(sell_notional, sell_fee_rate);    // Step 4: round trip = entry + exit, calculates exit fees to also consider exiting the position    // Example: 2 * 1.61 = 3.22    const int64_t total_trade_cost = 2 * trade_cost;    // Step 5: safety buffer - (in case, the order takes some extra slippage)    // Example: 1000 * 0.02% = 0.2    const int64_t trade_buffer = mul_div(buy_notional, margin_buffer_, RATE_SCALE);    // Step 6: net profit = gross profit - (total cost + buffer)    // Example: 20 - (3.22 + 0.2) = 20 - 3.42 = 16.58  -> profitable    const int64_t net_profit = gross_profit - (total_trade_cost + trade_buffer);    // if profit is <= 0, return empty result    // Example: if net_profit = -2 , skip trade    if (net_profit <= 0) return {};    // if Profitable, than return direction, qty and profit    return { dir, qty, net_profit };}// Direction 1: buy spot on ask and sell future on bidarbitrage_result arbitrage_checker::check_buy_spot_sell_future_arbitrage(const tick& spot_tick,                                                                         const tick& future_tick) const{    //skipping invalid ticks    if (!is_valid(spot_tick) || !is_valid(future_tick)) return {};    // simple check: future bid should be greater than spot ask    // Example: future bid = 102, spot ask = 100 -> 102 > 100 OK, continue    //          future bid = 99,  spot ask = 100 -> spread negative, skip    if (future_tick.bid <= spot_tick.ask) return {};    // Qty = min of both side to maximize trade fulfilment    // Example: spot ask_qty = 10, future bid_qty = 15 -> qty = 10    //          (cannot sell 15 if the buy_qty is only 10 - (will calculate wrong profit))    const int64_t qty = std::min(spot_tick.ask_qty, future_tick.bid_qty);    // Buy leg = spot (100), sell leg = future (102)    return build_result(arbitrage_direction::buy_spot_sell_future,                        spot_tick.ask, future_tick.bid, qty,                        spot_taker_fee_, future_taker_fee_);}// Direction 2: short spot on bid price and buy future on askarbitrage_result arbitrage_checker::check_sell_spot_buy_future_arbitrage(const tick& spot_tick,                                                                         const tick& future_tick) const{    if (!is_valid(spot_tick) || !is_valid(future_tick)) return {};    // Example: spot bid = 102, future ask = 100 -> 102 > 100 OK    //          spot bid = 99,  future ask = 100 -> skip    if (spot_tick.bid <= future_tick.ask) return {};    // Example: spot bid_qty = 8, future ask_qty = 12 -> qty = 8    const int64_t qty = std::min(spot_tick.bid_qty, future_tick.ask_qty);    // Ab buy leg = future , sell leg = spot    // swapped fees,  buy_fee = future fee, sell_fee = spot fee    return build_result(arbitrage_direction::sell_spot_buy_future,                        future_tick.ask, spot_tick.bid, qty,                        future_taker_fee_, spot_taker_fee_);}// check both direction and check profitable onearbitrage_result arbitrage_checker::evaluate_arbitrage(const tick& spot_tick,                                                       const tick& future_tick) const{    const auto a = check_buy_spot_sell_future_arbitrage(spot_tick, future_tick);    const auto b = check_sell_spot_buy_future_arbitrage(spot_tick, future_tick);    // Example: a.expected_profit = 16.58, b.expected_profit = 0    //          16.58 >= 0 -> return a    // if both direction returns 0, then it will return none on both side. to be continued ......    return (a.expected_profit >= b.expected_profit) ? a : b;}